import { MODEL,icon,esc,number,time,tag,modelTag,empty,heroGraph } from './ui.js';
import { GraphView } from './graph.js';
const $=id=>document.getElementById(id);
const NAV=[['工作空间',[['overview','home','项目总览'],['graph','graph','本体图谱'],['models','layers','七模型工作台']]],['语义建模',[['flows','flow','流程模型'],['queries','table','查询与报表'],['review','shield','校验与评审']]],['项目管理',[['jobs','jobs','建模任务'],['exports','download','版本与导出'],['settings','settings','能力与设置']]]];
const titles=Object.fromEntries(NAV.flatMap(([,items])=>items.map(([id,,label])=>[id,label])));
const S={boot:null,project:null,data:null,route:location.hash.split('/')[1]||'overview',type:'',context:'',search:'',page:1,modelView:'list',graphMode:'all',graphPrefs:{},flowId:'',flowSearch:'',flowLevel:'',reviewTab:'checks',snapshot:null,assistantMessages:[],assistantBusy:false};let graph=null,pollTimer=null,loadEpoch=0;
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'请求未完成');return d}
const projectAPI=(action='',extra='')=>`/projects/${S.project.id}/${action}${S.snapshot?'?snapshot='+encodeURIComponent(S.snapshot)+(extra?'&'+extra:''):extra?'?'+extra:''}`;
const nodes=()=>S.data?.nodes||[];const reviews=()=>new Map((S.data?.reviews||[]).map(r=>[r.node_id,r]));
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'check',17)+`<span>${esc(message)}</span>`;$('toast-root').append(el);setTimeout(()=>el.remove(),4500)}
function navigate(route){if(route===S.route){render();return}location.hash='/'+route}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">ONTOLOGY STUDIO / ${esc(S.project?.name||'WORKSPACE')}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function mainActions(){return `${S.data?`<button class="button" data-reanalyze>${icon('refresh',14)}重新分析</button>`:''}<button class="button primary" data-new>${icon('plus',15)}接入代码仓库</button>`}
function needData(){if(S.data)return false;const active=S.boot?.jobs.find(j=>j.project_id===S.project?.id&&['running','queued'].includes(j.status));$('content').innerHTML=heading('开始构建你的业务语义空间','接入代码仓库，让对象、行为与流程逐步变得清晰。',mainActions())+empty(active?'建模任务正在进行':'还没有可查看的本体快照',active?'平台正在提取源码中的业务语义。可以前往任务中心查看阶段与日志。':'选择本地 Java / Spring 工程，或输入 HTTPS Git 仓库地址开始分析。',active?'<button class="button primary" data-route="jobs">查看建模任务</button>':'<button class="button primary" data-reanalyze>开始分析此项目</button>');return true}
function modelCounts(){return Object.fromEntries(Object.keys(MODEL).map(k=>[k,nodes().filter(n=>n.model===k).length]))}
function activeSnapshot(){return S.project?.latest}
function renderNav(){$('navigation').innerHTML=NAV.map(([group,items])=>`<div class="nav-section">${group}</div>${items.map(([id,ic,label])=>`<a class="nav-link ${S.route===id?'active':''}" href="#/${id}">${icon(ic,16)}<span>${label}</span>${id==='jobs'&&S.boot?.jobs.some(j=>['running','queued'].includes(j.status))?'<span class="nav-count">'+S.boot.jobs.filter(j=>['running','queued'].includes(j.status)).length+'</span>':''}</a>`).join('')}`).join('');$('breadcrumb-current').textContent=titles[S.route]||'项目总览';$('project-title').textContent=S.project?.name||'选择代码项目';$('project-subtitle').textContent=S.project?.source_type==='git'?'HTTPS Git 仓库':'本地代码仓库';document.querySelector('.project-switch .project-avatar').textContent=(S.project?.name||'O').slice(0,1);$('engine-title').textContent=S.boot?.jobs.some(j=>j.status==='running')?'分析引擎运行中':'本地分析引擎';}
function render(){graph?.destroy();graph=null;renderNav();const fn={overview:renderOverview,graph:renderGraph,models:renderModels,flows:renderFlows,queries:renderQueries,review:renderReview,jobs:renderJobs,exports:renderExports,settings:renderSettings}[S.route]||renderOverview;fn();bindContent()}
function renderOverview(){
 if(!S.project){$('content').innerHTML=heading('从代码，读懂业务。','建立统一的业务语义，让每一次技术理解都有据可循。',mainActions())+empty('你的第一个本体项目','从一个代码仓库开始，构建对象、行为、规则与流程之间的关系。','<button class="button primary" data-new>接入代码仓库</button>');return}
 if(needData())return;const d=S.data,c=d.counts,checks=d.manifest.validation||[],passed=checks.filter(c=>c.passed).length,counts=modelCounts(),snap=d.snapshot,commit=snap.commit&&snap.commit!=='unavailable'?snap.commit.slice(0,8):'未记录';const metrics=[['M1',c.objects,'业务对象','聚合与实体的统一描述'],['M2',c.behaviors,'业务行为','从操作入口追溯实现'],['M6',counts.M6,'流程模型',`${c.lifecycleFlows||0} 条跨端点生命周期`],['M7',counts.M7,'查询契约','参数、返回结构与数据来源']];
 $('content').innerHTML=heading('从代码，读懂业务。','以源码为起点，连接业务知识，构建可追溯、可评审的七模型本体。',mainActions())+
 `<section class="hero"><div class="hero-content"><div class="hero-kicker">CODE TO ONTOLOGY</div><h2>让业务逻辑，不再藏在代码里</h2><p>从业务对象到端到端流程，将分散的实现连接成清晰的语义图谱。每一个模型元素，都有源码证据可循。</p><div class="hero-actions"><button class="button primary" data-route="graph">探索本体图谱 ${icon('arrow',14)}</button><button class="text-button" data-route="models">查看七模型 ${icon('chevron',13)}</button></div></div>${heroGraph()}</section>`+
 `<div class="stats-grid">${metrics.map(([k,n,label,foot])=>`<div class="stat-card" style="--model:${MODEL[k].color};--model-soft:${MODEL[k].soft}"><span class="stat-label">${label}</span><span class="stat-icon">${icon(MODEL[k].icon,17)}</span><strong class="stat-number">${number(n)}</strong><span class="stat-foot"><b>●</b> ${foot}</span></div>`).join('')}</div>`+
 `<div class="two-column"><section class="panel"><div class="panel-head"><h2>当前代码项目</h2><button class="text-button" data-projects>切换项目 ${icon('chevron',12)}</button></div><div class="panel-body"><div class="project-overview"><div class="repo-icon">${icon('git',23)}</div><div><h3>${esc(S.project.name)}</h3><div class="repo-subtitle">Java / Spring ${tag(snap.kind==='imported'?'已有建模结果':'静态分析完成','success')} ${tag('待领域评审','purple')}</div></div></div><div class="repo-path" title="${esc(S.project.path)}">${icon('folder',13)}<span class="overflow-clip">${esc(S.project.repo_url||S.project.path)}</span></div><div class="repo-details"><div><small>业务模块</small>${Object.keys(d.contexts).length} 个模块</div><div><small>源码版本</small><span class="mono">${esc(commit)}</span></div><div><small>模型关系</small>${number(d.edges.length)} 条关联</div></div><div class="repo-bottom"><span>${icon('clock',11)} ${snap.kind==='imported'?'导入于':'建模于'} ${time(snap.created_at)}</span><button class="text-button" data-route="exports">版本与产物 ${icon('arrow',12)}</button></div></div></section>
 <section class="panel"><div class="panel-head"><h2>模型质量概览</h2>${tag('结构校验','purple')}</div><div class="panel-body"><div class="quality-summary"><svg class="progress-ring" viewBox="0 0 70 70"><circle cx="35" cy="35" r="27" fill="none" stroke="#f0edf6" stroke-width="5"/><circle cx="35" cy="35" r="27" fill="none" stroke="#ae9bca" stroke-width="5" stroke-dasharray="${checks.length?passed/checks.length*169.65:0} 169.65" stroke-linecap="round"/></svg><div><h3>${passed}<span style="font-size:13px;color:#b8afc3"> / ${checks.length}</span></h3><p>模型引用与结构检查通过</p></div></div><div class="quality-meta"><div><strong>${Object.values(d.models['m7-report-model.yaml']?.query_reports||[]).reduce((n,q)=>n+(q.resultColumns||[]).length,0)}</strong><small>查询返回字段</small></div><div><strong>${(d.reviews||[]).filter(r=>r.status==='confirmed').length}</strong><small>已确认语义元素</small></div></div><div class="mini-bars">${Array.from({length:20},()=>'<i></i>').join('')}</div></div></section></div>`+
 `<div class="section-title"><div><h2>七模型语义空间</h2><p>不同视角，共同描述同一份业务知识</p></div><button class="text-button" data-route="models">进入建模工作台 ${icon('arrow',13)}</button></div><div class="model-grid">${Object.entries(MODEL).map(([k,m])=>`<button class="model-card" data-model="${k}" style="--model:${m.color};--model-soft:${m.soft}"><div class="model-icon"><span>${icon(m.icon,16)}</span><span class="model-code">${k}</span></div><h3>${m.name}</h3><strong class="count">${number(counts[k])}<small>个元素</small></strong></button>`).join('')}</div>`+
 `<div class="section-title"><h2>业务域导航 <span style="color:#b9afc5;font-size:10px;font-weight:400;margin-left:9px">${Object.keys(d.contexts).length} 个模块</span></h2><button class="text-button" data-route="models">查看覆盖矩阵 ${icon('arrow',13)}</button></div><div class="domain-list">${Object.entries(d.contexts).slice(0,12).map(([k,v])=>`<button class="domain-chip" data-context="${k}"><i></i>${esc(v)}<span>${nodes().filter(n=>n.context===k&&n.model!=='CTX').length} 个元素</span></button>`).join('')}</div>`;
}
function filterBar(placeholder='搜索名称、标识或类名',extra=''){return `<div class="toolbar"><input class="field-input search-input" id="model-search" placeholder="${placeholder}" value="${esc(S.search)}"><select class="field-input" id="context-filter"><option value="">全部业务域</option>${Object.entries(S.data.contexts).map(([k,v])=>`<option value="${k}" ${S.context===k?'selected':''}>${esc(v)}</option>`).join('')}</select>${extra}<span class="toolbar-note">源码证据可追溯</span></div>`}
function filtered(list){const q=S.search.toLowerCase();return list.filter(n=>(!S.context||n.context===S.context)&&(!q||JSON.stringify([n.label,n.id,n.alias,n.endpoint]).toLowerCase().includes(q)))}
function table(list,kind='models'){const total=list.length,limit=12,max=Math.max(1,Math.ceil(total/limit));S.page=Math.min(max,S.page);const visible=list.slice((S.page-1)*limit,S.page*limit),rv=reviews();return `<div class="table-grid"><table class="data-table"><thead><tr><th>模型元素 / 标识</th><th>模型类型</th><th>业务域</th><th>${kind==='queries'?'参数 / 返回列':'证据'}</th><th>评审状态</th><th></th></tr></thead><tbody>${visible.map(n=>{const r=rv.get(n.id);return `<tr data-node="${esc(n.id)}" tabindex="0"><td><strong>${esc(n.label)}</strong><small>${esc(n.id)}</small></td><td>${modelTag(n.model)}</td><td>${esc(S.data.contexts[n.context]||n.context)}</td><td>${kind==='queries'?`${n.parameters?.length||0} / ${n.resultColumns?.length||0}`:n.evidence?.length?`${n.evidence.length} 处源码`:'关联模型'}</td><td>${tag(r?.status==='confirmed'?'已确认':r?.status==='needs_changes'?'需修订':n.humanEdited?'人工修订':'未评审',r?.status==='confirmed'?'success':r?.status==='needs_changes'?'warning':'neutral')}</td><td class="arrow-cell">${icon('chevron',14)}</td></tr>`}).join('')||`<tr><td colspan="6">${empty('没有匹配的模型','调整业务域或搜索关键词后再试。')}</td></tr>`}</tbody></table></div><div class="pagination"><span>共 ${total} 个元素 · 第 ${S.page} / ${max} 页</span><div class="page-buttons"><button class="button small" data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><button class="button small" data-page="${S.page+1}" ${S.page===max?'disabled':''}>下一页</button></div></div>`}
function renderModels(){if(needData())return;const counts=modelCounts();$('content').innerHTML=heading('七模型工作台','在统一语义空间中查看、修订与评审模型，每一次理解都保留证据。',`<div class="page-view-switch"><button data-modelview="list" class="${S.modelView==='list'?'active':''}">元素列表</button><button data-modelview="matrix" class="${S.modelView==='matrix'?'active':''}">覆盖矩阵</button></div>`)+`<div class="tabs"><button class="tab ${!S.type?'active':''}" data-type="">全部模型 ${nodes().filter(n=>n.model!=='CTX').length}</button>${Object.entries(MODEL).map(([k,m])=>`<button class="tab ${S.type===k?'active':''}" data-type="${k}">${k} ${m.name} <small>${counts[k]}</small></button>`).join('')}</div><section class="panel">${filterBar()}${S.modelView==='matrix'?matrix():table(filtered(nodes().filter(n=>n.model!=='CTX'&&(!S.type||n.model===S.type))))}</section>`}
function matrix(){return `<div class="table-grid"><table class="data-table matrix-table"><thead><tr><th>业务模块</th>${Object.keys(MODEL).map(k=>`<th>${k}</th>`).join('')}<th>覆盖说明</th></tr></thead><tbody>${Object.entries(S.data.contexts).filter(([k,v])=>(!S.context||k===S.context)&&(!S.search||v.includes(S.search)||k.includes(S.search))).map(([c,label])=>`<tr><td><strong>${esc(label)}</strong><small>${esc(c)}</small></td>${Object.keys(MODEL).map(k=>{const n=nodes().filter(n=>n.context===c&&n.model===k).length;return `<td>${n?`<button class="matrix-number" data-matrix-context="${c}" data-matrix-model="${k}">${n}</button>`:'<span style="color:#d2c7dd">—</span>'}</td>`}).join('')}<td>${tag(c==='installment'?'开发中':c==='web'?'界面与代理':'静态反向模型',c==='installment'?'warning':'neutral')}</td></tr>`).join('')}</tbody></table></div>`}
function renderGraph(){if(needData())return;$('content').innerHTML=heading('探索业务本体图谱','把分散的业务实现连接起来，沿着关系找到定义与证据。',`<div class="page-view-switch"><button data-graph-mode="all" class="${S.graphMode==='all'?'active':''}">全部本体</button><button data-graph-mode="domains" class="${S.graphMode==='domains'?'active':''}">业务域</button><button data-graph-mode="objects" class="${S.graphMode==='objects'?'active':''}">对象关系</button></div>`)+`<section class="panel" style="margin-bottom:15px">${filterBar('在当前项目中搜索',`<select id="graph-model-filter" class="field-input"><option value="">全部模型类型</option>${Object.entries(MODEL).map(([k,m])=>`<option value="${k}" ${S.type===k?'selected':''}>${k} ${m.name}</option>`).join('')}</select>`)}</section><div class="graph-panel" id="graph-container"></div>`;graph=new GraphView($('graph-container'),S.data,{mode:S.graphMode,context:S.context,type:S.type,view:S.graphPrefs,onViewChange:v=>{S.graphPrefs=v},onClear:closeInspector,onSelect:n=>openNode(n),onOpen:n=>{if(n.model==='CTX'){S.context=n.context;S.graphMode='all';render()}else if(n.model==='M6'){S.flowId=n.id;navigate('flows')}}});if(S.search){const matches=filtered(nodes());const n=matches.find(n=>graph.nodes.some(x=>x.id===n.id));if(n)graph.selectById(n.id,true)}}
function renderFlows(){if(needData())return;const flows=nodes().filter(n=>n.model==='M6').sort((a,b)=>(a.modelingLevel==='BUSINESS_LIFECYCLE'?0:1)-(b.modelingLevel==='BUSINESS_LIFECYCLE'?0:1));const visible=flows.filter(n=>(!S.context||n.context===S.context)&&(!S.flowLevel||n.modelingLevel===S.flowLevel)&&(!S.flowSearch||JSON.stringify([n.label,n.id]).toLowerCase().includes(S.flowSearch.toLowerCase())));const active=visible.find(f=>f.id===S.flowId)||visible[0];if(active)S.flowId=active.id;
 $('content').innerHTML=heading('流程模型','从业务生命周期下钻到应用执行，查看分支、异常与跨对象协同。',`<select class="field-input" id="context-filter"><option value="">全部业务域</option>${Object.entries(S.data.contexts).map(([c,v])=>`<option value="${c}" ${c===S.context?'selected':''}>${esc(v)}</option>`).join('')}</select>`)+`<div class="flow-layout"><div class="flow-library"><div class="flow-library-head"><div style="display:flex;justify-content:space-between;color:#9e8cb1;font-size:11px">流程目录 <span>${visible.length} 条</span></div><input id="flow-search" class="field-input" placeholder="搜索流程" value="${esc(S.flowSearch)}"><select id="flow-level" class="field-input"><option value="">全部流程层级</option><option value="BUSINESS_LIFECYCLE" ${S.flowLevel==='BUSINESS_LIFECYCLE'?'selected':''}>业务生命周期</option><option value="APPLICATION_ORCHESTRATION" ${S.flowLevel==='APPLICATION_ORCHESTRATION'?'selected':''}>应用执行流程</option></select></div>${visible.map(f=>`<button class="flow-item ${f.id===active?.id?'active':''}" data-flow="${esc(f.id)}"><span class="flow-type">${f.modelingLevel==='BUSINESS_LIFECYCLE'?'◇ 业务生命周期':'⌁ 应用执行流程'} · ${esc(S.data.contexts[f.context])}</span><strong>${esc(f.label)}</strong><small>${f.activities?.length||0} 个活动 · ${f.activities?.filter(a=>a.activityType==='GATEWAY').length||0} 个网关</small></button>`).join('')||empty('暂无匹配流程','该范围没有可识别的执行流程。')}</div><div class="graph-panel" id="flow-graph"></div></div>`;
 graph=new GraphView($('flow-graph'),S.data,{mode:'flow',flow:active,onSelect:a=>openNode({...a,flow:active}),onOpen:a=>{if(a.subFlowRef){S.flowId=a.subFlowRef;S.context='';S.flowLevel='';S.flowSearch='';closeInspector();render()}}});if(active){const toolbar=$('flow-graph').querySelector('.graph-toolbar');toolbar.insertAdjacentHTML('beforeend',`<button class="button small" data-node="${esc(active.id)}">流程详情 ${icon('chevron',12)}</button>`)}}
function renderQueries(){if(needData())return;const list=filtered(nodes().filter(n=>n.model==='M7'));$('content').innerHTML=heading('查询与报表','从输入条件到返回结构，追溯每一份业务查询的数据语义。',`<button class="button" data-route="exports">${icon('download',14)}导出查询模型</button>`)+`<div class="notice">${icon('info',15)}<span>直接 DTO 映射、已核验统计表达式与待评审候选分别标注。查询契约覆盖不等于所有业务公式均已证明。</span></div><section class="panel">${filterBar('搜索查询、报表或接口')}${table(list,'queries')}</section>`}
function renderReview(){if(needData())return;const checks=S.data.manifest.validation||[],rv=reviews(),confirmed=[...rv.values()].filter(r=>r.status==='confirmed').length,needs=[...rv.values()].filter(r=>r.status==='needs_changes').length;const list=filtered(nodes().filter(n=>n.model!=='CTX'&&rv.get(n.id)?.status!=='confirmed'));$('content').innerHTML=heading('校验与评审','让结构检查与业务判断各司其职，将每一次确认沉淀为可信语义。')+`<div class="review-overview"><div class="review-metric"><strong>${checks.filter(c=>c.passed).length} / ${checks.length}</strong><span>结构与引用检查通过</span></div><div class="review-metric"><strong>${confirmed}</strong><span>人工确认的语义元素</span></div><div class="review-metric"><strong>${needs}</strong><span>标记为需要修订</span></div></div><div class="tabs"><button class="tab ${S.reviewTab==='checks'?'active':''}" data-reviewtab="checks">结构校验</button><button class="tab ${S.reviewTab==='pending'?'active':''}" data-reviewtab="pending">语义待办 ${nodes().filter(n=>n.model!=='CTX').length-confirmed}</button><button class="tab ${S.reviewTab==='lineage'?'active':''}" data-reviewtab="lineage">血缘质量</button></div>`+(S.reviewTab==='checks'?`<section class="panel"><div class="panel-head"><h2>模型结构校验结果</h2>${tag('不替代业务验收','purple')}</div><div class="check-list">${checks.map(c=>`<div class="check-row"><span class="check-icon" style="${!c.passed?'background:#fff0ee;color:#bd8181':''}">${icon(c.passed?'check':'close',12)}</span><span>${esc(checkName(c.check))}</span><small>${c.count} 项引用</small></div>`).join('')}</div></section>`:S.reviewTab==='pending'?`<section class="panel">${filterBar('搜索待评审模型')}${table(list)}</section>`:lineagePanel());}
function checkName(s){const known={'M2 USER_ACTION → MU action coverage':'用户触发行为具有可追溯的界面入口','MU → M2 behavior existence':'界面引用的业务行为均存在','M7 ↔ M2 one-to-one':'查询模型与业务行为双向一对一','M6 behavior references':'流程中的行为引用完整','M1 reference targets':'对象之间的引用目标存在','M2 syncTriggers references':'同步联动规则与行为引用有效','Graph references':'图谱关系两端均存在','Unique node identifiers':'本体元素标识唯一','M6 one START and valid END activities':'每条流程具有唯一开始和合法结束','M6 activity, behavior, subflow and rule references':'流程活动、子流程及规则引用有效','M6 all activities reachable':'所有流程活动从开始节点可达','M6 all activity paths can reach an END':'所有活动存在到达结束的路径','M6 gateways have conditional/default branches':'网关条件与默认分支合法','M6 role references':'人工任务角色引用合法','M6 business object references are roots':'流程对象均引用有效聚合根','M6 SUB_FLOW_CALL graph is acyclic':'子流程调用不存在递归环','M7 unique QUERY behavior and bidirectional binding':'查询行为唯一且双向绑定','M7 valid root sources and exactly one primary':'查询具有唯一主来源及有效业务对象','M7 source aliases and join references':'查询来源别名与关联引用有效','M7 parameter and response contract populated':'查询参数和返回结构已恢复','M7 contains no role/rule/flow permission references':'查询模型遵循跨模型引用边界','M7 proven DTO mappings resolve to M1 fields':'已证明的 DTO 映射可解析到对象字段','M7 REPORT objects include reportOptions':'固定报表具有展示定义','Payment SETTLED idempotence and ACCEPTED guard preserved':'支付幂等与清算前置条件保留','Report generation retains failure-write and rethrow':'报表生成保留失败状态与异常回传','Transaction report distinguishes page and global sums':'交易报表区分页合计与全量合计','POST report generation remains COMMAND':'写入报表运行记录的操作仍归类为命令'};return known[s]||s}
function lineagePanel(){const columns=nodes().filter(n=>n.model==='M7').flatMap(n=>n.resultColumns||[]),counts=columns.reduce((o,c)=>(o[c.mappingStatus]=(o[c.mappingStatus]||0)+1,o),{});return `<section class="panel"><div class="panel-head"><h2>查询返回字段的证据状态</h2>${tag(`${columns.length} 个字段`,'purple')}</div><div class="panel-body"><div class="notice">${icon('info',16)}<span>只将存在明确构造参数或计算公式的映射标记为已核验。同名候选和仅恢复契约的字段单独保留，避免把猜测当成业务事实。</span></div>${Object.entries({DTO_CONSTRUCTOR_VERIFIED:'DTO 构造映射已核对',SOURCE_VERIFIED:'统计表达式已核验',NAME_MATCH_REVIEW:'同名候选 · 需要评审',DTO_CONTRACT_ONLY:'返回结构已恢复 · 血缘待补充'}).map(([k,v])=>`<div class="setting-row"><span>${v}</span><strong>${counts[k]||0}</strong></div>`).join('')}</div></section>`}
function renderJobs(){const list=S.boot.jobs;const labels={completed:['已完成','success'],running:['分析中','purple'],queued:['排队中','neutral'],failed:['失败','error'],cancelled:['已取消','neutral']};$('content').innerHTML=heading('建模任务','每一次分析都有过程、有结果，也有清晰的失败原因。',`<button class="button primary" data-new>${icon('plus',15)}新建建模任务</button>`)+(list.length?list.map(j=>`<section class="job-card"><div class="job-title"><span class="repo-icon" style="width:33px;height:33px">${icon('jobs',17)}</span><strong>${esc(j.project_name)}</strong>${tag(...(labels[j.status]||[j.status,'neutral']))}</div><div class="job-meta">${esc(j.id)} · ${time(j.started_at||j.created_at)} ${j.finished_at?'→ '+time(j.finished_at):''}</div><div style="display:flex;justify-content:space-between;color:#a28bb2;font-size:11px"><span>${esc(j.stage)}</span><span>${j.progress}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${j.progress}%"></div></div><div class="job-stages">${['准备仓库','源码快照','七模型生成','校验与溯源','保存结果'].map((s,i)=>`<span class="${j.progress>=(i+1)*20?'done':''}">${s}</span>`).join('')}</div>${j.error?`<p class="job-error">${esc(j.error)}</p>`:''}<details class="job-events" ${['running','failed'].includes(j.status)?'open':''}><summary style="font-size:10px;color:#b6a1c3;cursor:pointer">查看分析日志 · ${j.events.length} 条</summary>${j.events.map(e=>`<div class="job-event"><time>${time(e.time)}</time><span>${esc(e.message)}</span></div>`).join('')}</details><div style="display:flex;justify-content:flex-end;margin-top:15px;gap:8px">${['running','queued'].includes(j.status)?`<button class="button small danger" data-cancel="${j.id}">${icon('stop',12)}取消任务</button>`:j.status==='completed'?`<button class="button small" data-job-project="${j.project_id}">查看建模结果 ${icon('arrow',12)}</button>`:`<button class="button small" data-retry="${j.project_id}">重新分析</button>`}</div></section>`).join(''):empty('还没有运行任务','当前 CardDemo 数据来自已有建模快照。点击“重新分析”可以运行一次真实的源码提取。',S.project?'<button class="button primary" data-reanalyze>重新分析当前项目</button>':'<button class="button primary" data-new>接入代码仓库</button>'));}
function exportURL(format,file){return `/api/projects/${S.project.id}/export?format=${format}&snapshot=${encodeURIComponent(S.data.snapshot.id)}${file?'&file='+encodeURIComponent(file):''}`}
function renderExports(){if(needData())return;const list=S.projectSnapshots||[],snapshot=S.data.snapshot;$('content').innerHTML=heading('版本与导出','保留每一次建模结果，将语义资产带到评审、开发与后续分析中。',`<select class="field-input snapshot-select" id="snapshot-select"><option value="">当前最新快照</option>${list.map(s=>`<option value="${s.id}" ${S.snapshot===s.id?'selected':''}>${time(s.created_at)} · ${s.kind==='imported'?'导入基线':'分析快照'}</option>`).join('')}</select>`)+`<div class="export-grid">${[['json','layers','完整模型数据','七模型、图谱关系、源码证据和评审记录，便于继续加工与系统集成。','JSON'],['html','layout','离线建模报告','可离线搜索模型目录、查看属性和证据，方便保存与团队评审。','HTML'],['yaml','file','七模型文件','按模型分别导出 YAML 1.2 文件，保留可追溯的业务语义与待评审状态。','YAML']].map(([format,ic,name,desc,ext])=>`<div class="export-card"><div class="model-icon">${icon(ic,23)}</div><h3>${name}</h3><p>${desc}</p>${format==='yaml'?'<button class="button" data-scroll-yaml>选择模型文件</button>':`<a class="button" href="${exportURL(format)}" download>${icon('download',14)}导出 ${ext}</a>`}</div>`).join('')}</div><section class="panel" id="yaml-files"><div class="panel-head"><h2>七模型产物</h2>${tag('YAML 1.2 · JSON 序列化','purple')}</div><div class="panel-body"><div class="card-action-list">${Object.entries(MODEL).map(([k,m])=>{const file=Object.keys(S.data.models).find(f=>f.startsWith(k==='MU'?'mu-':k.toLowerCase()+'-'));return file?`<a class="button" href="${exportURL('yaml',file)}" download>${icon('file',13)}${k} ${m.name} ${icon('download',12)}</a>`:''}).join('')}</div></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>模型快照历史</h2><small style="color:#b8a4c6">评审与修订按快照独立保存</small></div><div class="table-grid"><table class="data-table"><thead><tr><th>生成时间</th><th>来源</th><th>本体元素</th><th>关联关系</th><th>状态</th><th></th></tr></thead><tbody>${list.map(s=>`<tr data-snapshot="${s.id}"><td><strong>${time(s.created_at)}</strong><small>${esc(s.id)}</small></td><td>${s.kind==='imported'?'已有结果导入':'源码分析'}</td><td>${s.summary.nodes}</td><td>${s.summary.edges}</td><td>${tag(s.id===snapshot.id?'正在查看':'历史快照',s.id===snapshot.id?'purple':'neutral')}</td><td>${icon('chevron',14)}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderSettings(){$('content').innerHTML=heading('能力与设置','轻量技术原型，清晰的能力范围，可追溯的建模结果。')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>分析能力</h2>${tag('本地运行','success')}</div><div class="panel-body">${[['深度分析适配器','Java / Spring'],['对象识别','JPA 实体、领域对象与 record'],['行为识别','Spring REST → 应用服务'],['流程恢复','条件分支、循环、异常与子流程'],['查询契约','参数、DTO 返回结构与映射'],['模型框架','七模型 v9']].map(([a,b])=>`<div class="setting-row"><span>${a}</span><span>${b}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>All-in-one 运行环境</h2>${tag('技术原型','purple')}</div><div class="panel-body">${[['服务','Node.js 原生 HTTP'],['存储','SQLite · 本机文件'],['分析器','Python 标准库'],['界面','原生模块 · 无构建步骤'],['证据助手','本地语义检索 · SSE'],['配置方式','环境变量 / 启动参数']].map(([a,b])=>`<div class="setting-row"><span>${a}</span><span>${b}</span></div>`).join('')}</div></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>能力边界</h2><button class="text-button" id="settings-guide">查看完整说明 ${icon('external',12)}</button></div><div class="panel-body"><ul class="scope-list"><li>本地目录或 HTTPS Git 仓库均可接入。远程克隆不支持交互式登录，私有仓库可先在本机克隆后接入。</li><li>只读取分析所需的源码和配置，不执行目标仓库的构建命令、安装脚本或工作区钩子。</li><li>源码输入限 6000 个分析文件 / 60MB。其他语言会明确提示当前不支持深度建模。</li><li>结构校验不替代领域评审。未确认的角色、血缘和规则不会补造为已实现能力。</li><li>证据助手基于本地模型检索；当前没有调用外部大模型，不将检索结果包装成生成式推理。</li></ul></div></section>`;}
function bindContent(){
 const search=$('model-search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;S.search=e.target.value;S.page=1;render();const n=$('model-search');n?.focus();n?.setSelectionRange(pos,pos)};
 const c=$('context-filter');if(c)c.onchange=e=>{S.context=e.target.value;S.page=1;render()};
 const g=$('graph-model-filter');if(g)g.onchange=e=>{S.type=e.target.value;render()};
 const fs=$('flow-search');if(fs)fs.oninput=e=>{const pos=e.target.selectionStart;S.flowSearch=e.target.value;render();$('flow-search')?.focus();$('flow-search')?.setSelectionRange(pos,pos)};
 const fl=$('flow-level');if(fl)fl.onchange=e=>{S.flowLevel=e.target.value;render()};
 const sn=$('snapshot-select');if(sn)sn.onchange=async e=>{S.snapshot=e.target.value||null;await loadProjectData();render()};
 $('settings-guide')?.addEventListener('click',guide);
}
const lineageNames={DTO_CONSTRUCTOR_VERIFIED:'构造映射已核对',SOURCE_VERIFIED:'表达式已核验',NAME_MATCH_REVIEW:'同名候选 · 待评审',DTO_CONTRACT_ONLY:'响应契约 · 血缘待补充'};
function getNode(id){return nodes().find(n=>n.id===id)}
function nodeDetails(n){let html='';
 if(n.attributes?.length)html+=`<div class="detail-caption">对象属性 · ${n.attributes.length}</div>${n.attributes.map(a=>`<div class="detail-row"><span class="detail-type">${esc(a.javaType||a.type)}</span><b>${esc(a.label||a.name)}</b>${a.required?' <small style="color:#c6a9b1">*</small>':''}<div style="font:9px ui-monospace,monospace;color:#c3adc9">${esc(a.name)}</div>${a.targetAggregate?`<button class="text-button" style="font-size:9px;margin-top:6px" data-node="${esc(a.targetAggregate)}">引用 ${esc(getNode(a.targetAggregate)?.label||a.targetAggregate)} ↗</button>`:''}</div>`).join('')}`;
 if(n.lifecycle?.length)html+=`<div class="detail-caption">生命周期状态</div><div class="card-action-list">${n.lifecycle.map(x=>tag(x,'purple')).join('')}</div>`;
 if(n.endpoint)html+=`<div class="detail-caption">行为入口</div><div class="detail-code">${esc(n.endpoint.method)} ${esc(n.endpoint.path)}</div>`;
 if(n.conditionExpression||n.sourceCode)html+=`<div class="detail-caption">${n.conditionExpression?'分支条件':'执行语句'}</div><pre class="detail-code">${esc(n.conditionExpression||n.sourceCode)}</pre>`;
 if(n.activities)html+=`<div class="detail-caption">流程结构</div><div class="detail-row"><b>${n.activities.length}</b> 个活动 · <b>${n.activities.filter(a=>a.activityType==='GATEWAY').length}</b> 个条件网关<br>${n.modelingLevel==='BUSINESS_LIFECYCLE'?'跨端点业务生命周期':'由应用服务源码恢复的执行流程'}</div><button class="button full small" style="margin-top:10px" data-open-flow="${esc(n.id)}">${icon('flow',14)}展开流程拓扑</button>`;
 if(n.subFlowRef)html+=`<button class="button full small" data-open-flow="${esc(n.subFlowRef)}">打开执行子流程 ${icon('external',13)}</button>`;
 if(n.model==='M7'){
  html+=`<div class="detail-caption">查询来源</div>${(n.sourceObjects||[]).map(o=>`<button class="related-node" data-node="${esc(o.objectRef)}">${icon('box',13)}${esc(getNode(o.objectRef)?.label||o.objectRef)} ${o.primary?tag('主来源','purple'):''}<span>${icon('chevron',12)}</span></button>`).join('')}<div class="detail-caption">输入参数 · ${n.parameters?.length||0}</div>${n.parameters?.length?n.parameters.map(p=>`<div class="detail-row"><span class="detail-type">${esc(p.javaType||p.dataType)}</span><b>${esc(p.name)}</b><br>${p.required?'必填':'可选'} · ${p.binding==='PATH'?'路径参数':p.binding==='QUERY'?'查询参数':'请求体'}${p.defaultValue!==undefined?' · 默认 '+esc(p.defaultValue):''}</div>`).join(''):'<p class="detail-description">无显式输入参数</p>'}<div class="detail-caption">返回字段 · ${n.resultColumns?.length||0}</div>${(n.resultColumns||[]).map(c=>`<details class="detail-row"><summary style="cursor:pointer;list-style:none"><span class="detail-type">${esc(c.javaType||c.dataType)}</span><b>${esc(c.name)}</b><br><small style="color:#b5a1c2">${lineageNames[c.mappingStatus]||esc(c.mappingStatus)}</small></summary><div class="detail-code" style="margin-top:9px">${esc(c.sourceExpression||'业务表达式尚未确认')}${c.conversionExpression?'\n转换：'+esc(c.conversionExpression):''}</div>${(c.evidence||[]).map(e=>`<button class="text-button" style="font-size:9px;margin-top:7px" data-source="${esc(e.path)}" data-line="${e.line}">${icon('code',11)} 查看字段证据</button>`).join('')}</details>`).join('')}`;
  if(n.aggregationSemantics||n.composition)html+=`<div class="detail-caption">计算与组合口径</div><pre class="detail-code">${esc(JSON.stringify(n.aggregationSemantics||n.composition,null,2))}</pre>`;
 }
 if(n.expression)html+=`<div class="detail-caption">规则表达式</div><pre class="detail-code">${esc(n.expression)}</pre>`;
 if(n.invariants?.length)html+=`<div class="detail-caption">局部约束 · ${n.invariants.length}</div>${n.invariants.map(i=>`<details class="detail-row"><summary>${esc(i.name)}</summary><pre class="detail-code">${esc(i.sourceFragment||i.description)}</pre></details>`).join('')}`;
 if(n.notes)html+=`<div class="detail-caption">建模说明</div><p class="detail-description">${esc(n.notes)}</p>`;
 return html;
}
function openNode(value){const n=typeof value==='string'?getNode(value):value;if(!n)return;if(S.route==='graph')graph?.selectById(n.id);const r=reviews().get(n.id),isActivity=!!n.activityId;const related=(S.data?.edges||[]).filter(e=>e.source===n.id||e.target===n.id).slice(0,18);$('inspector').classList.remove('hidden');$('inspector').innerHTML=`<div class="inspector-head"><button class="icon-button close" data-close-inspector aria-label="关闭模型详情">${icon('close',17)}</button>${modelTag(n.model)}${n.humanEdited?' '+tag('人工修订','purple'):''}<h2>${esc(n.label)}</h2><div class="node-id">${esc(n.id)}</div></div><div class="inspector-body">${n.description?`<div class="detail-caption">语义定义</div><p class="detail-description">${esc(n.description)}</p>`:''}${nodeDetails(n)}${n.evidence?.length?`<div class="detail-caption">源码证据</div>${n.evidence.slice(0,5).map(e=>`<div class="evidence-card">${icon('file',12)} ${esc(e.path.split('/').pop())}:${e.line}<div class="evidence-path">${esc(e.path)}</div><button class="button small" data-source="${esc(e.path)}" data-line="${e.line}">${icon('code',12)}查看源码</button>${e.sha256?`<small style="display:block;margin-top:7px;color:#c7b0d2">SHA256 ${e.sha256.slice(0,12)}…</small>`:''}</div>`).join('')}`:''}${related.length?`<div class="detail-caption">关联元素 · ${related.length}</div>${related.map(e=>{const other=getNode(e.source===n.id?e.target:e.source);return other?`<button class="related-node" data-node="${esc(other.id)}">${icon(e.source===n.id?'arrow':'chevron',12)}<span>${esc(other.label)}<small style="display:block;color:#c3accc;margin-top:3px">${esc(e.label)}</small></span><span>${other.model}</span></button>`:''}).join('')}`:''}${!isActivity&&n.model!=='CTX'?`<div class="detail-caption">领域评审</div><div class="detail-row">${tag(r?.status==='confirmed'?'已确认':r?.status==='needs_changes'?'需要修订':'尚未评审',r?.status==='confirmed'?'success':'neutral')}${r?.note?`<p style="margin:9px 0 0">${esc(r.note)}</p>`:''}</div>`:''}<details style="margin-top:17px"><summary style="font-size:10px;color:#bea7ca;cursor:pointer">查看完整模型数据</summary><pre class="detail-code">${esc(JSON.stringify({...n,el:undefined},null,2))}</pre></details></div>${!isActivity&&n.model!=='CTX'?`<div class="inspector-actions"><button class="button small" data-edit="${esc(n.id)}">${icon('edit',13)}编辑语义</button><button class="button primary small" data-review="${esc(n.id)}">${icon('check',13)}评审此元素</button></div>`:''}`;}
function closeInspector(){$('inspector').classList.add('hidden')}
function modal(title,sub,content,footer='',wide=false){$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}" style="${wide?'width:min(820px,100%)':''}"><header class="modal-head"><button class="icon-button close" data-close-modal aria-label="关闭对话框">${icon('close',18)}</button><h2>${title}</h2><p>${sub}</p></header><div class="modal-body">${content}</div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;setTimeout(()=>$('modal-root').querySelector('input,textarea,select,button:not(.close)')?.focus(),20)}
function closeModal(){$('modal-root').innerHTML=''}
function newRepository(){let sourceType='local';modal('接入代码仓库','从真实源码开始，建立可追溯的业务语义空间。',`<form id="repository-form"><div class="source-tabs"><button type="button" class="source-tab active" data-source-tab="local">${icon('folder',15)}本地目录</button><button type="button" class="source-tab" data-source-tab="git">${icon('git',15)}HTTPS Git 仓库</button></div><div id="repo-error"></div><div class="form-field"><label class="field-label" for="repo-name">项目名称</label><input id="repo-name" class="field-input" required maxlength="100" placeholder="例如：信用卡核心业务"></div><div class="form-field"><label class="field-label" for="repo-location" id="repo-location-label">代码仓库路径</label><input id="repo-location" class="field-input" required placeholder="/Users/you/workspace/project"><small id="repo-location-help">填写已有代码工程的绝对路径。分析时只读扫描，不修改原仓库。</small></div><div class="adapter-card">${icon('layers',21)}<div><b>Java / Spring · 七模型分析适配器</b>识别业务对象、REST 行为、流程分支与查询契约。<br>当前原型暂不支持其他语言的深度语义建模。</div></div></form>`,`<small>分析结果按任务独立保存。<br>不执行仓库中的安装或构建脚本。</small><button type="submit" form="repository-form" class="button primary" id="create-repository">${icon('bolt',14)}接入并开始建模</button>`);
 $('modal-root').querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{sourceType=b.dataset.sourceTab;document.querySelectorAll('[data-source-tab]').forEach(t=>t.classList.toggle('active',t===b));$('repo-location').value='';$('repo-location').placeholder=sourceType==='local'?'/Users/you/workspace/project':'https://github.com/organization/repository.git';$('repo-location-label').textContent=sourceType==='local'?'代码仓库路径':'HTTPS Git 地址';$('repo-location-help').textContent=sourceType==='local'?'填写已有代码工程的绝对路径。分析时只读扫描，不修改原仓库。':'使用无需交互登录的 HTTPS 地址；私有仓库建议先克隆到本机再接入。'});
 $('repository-form').onsubmit=async e=>{e.preventDefault();const button=$('create-repository');button.disabled=true;button.textContent='正在创建分析任务…';try{const result=await api('/projects',{method:'POST',body:JSON.stringify({name:$('repo-name').value,repository:$('repo-location').value})});closeModal();S.snapshot=null;await refreshBootstrap();await chooseProject(result.project.id,false);navigate(result.duplicate?'overview':'jobs');if(S.route==='jobs')render();toast(result.duplicate?'该仓库已接入，已切换到现有项目':'代码仓库已接入，分析任务已创建');schedulePoll()}catch(error){$('repo-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;button.disabled=false;button.innerHTML=icon('bolt',14)+'接入并开始建模'}};
}
function projectPicker(){modal('代码项目','选择一个项目继续建模，或接入新的代码仓库。',S.boot.projects.map(p=>`<button class="project-list-item" data-pick-project="${p.id}"><span class="project-avatar">${esc(p.name.slice(0,1))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.repo_url||p.path)}</small></span>${tag(p.id===S.project?.id?'当前项目':p.latest?`${p.latest.summary.nodes} 个元素`:'待分析',p.id===S.project?.id?'purple':'neutral')}</button>`).join('')||empty('还没有项目','接入一个代码仓库开始。'),`<small>所有项目与快照保存在本机。</small><button class="button primary" id="picker-new">${icon('plus',14)}接入仓库</button>`);$('picker-new').onclick=newRepository;document.querySelectorAll('[data-pick-project]').forEach(b=>b.onclick=async()=>{closeModal();await chooseProject(b.dataset.pickProject);toast('已切换代码项目')})}
function editNode(id){const n=getNode(id);modal('修订模型语义','人工修订独立于源码证据保存，元素标识与引用关系保持稳定。',`<form id="edit-form"><div class="form-field"><label class="field-label" for="edit-label">模型名称</label><input id="edit-label" class="field-input" value="${esc(n.label)}" required maxlength="160"></div><div class="form-field"><label class="field-label" for="edit-description">语义描述</label><textarea id="edit-description" class="field-input">${esc(n.description||'')}</textarea></div><div class="notice">${icon('info',15)}<span>本次修订只作用于当前模型快照；重新分析会创建新快照，不会改写业务源码。</span></div></form>`,`<small>${esc(n.id)}</small><button class="button primary" type="submit" form="edit-form" id="save-edit">保存修订</button>`);$('edit-form').onsubmit=async e=>{e.preventDefault();const b=$('save-edit');b.disabled=true;try{await api(`/projects/${S.project.id}/nodes/${encodeURIComponent(id)}?snapshot=${S.data.snapshot.id}`,{method:'PATCH',body:JSON.stringify({label:$('edit-label').value,description:$('edit-description').value})});closeModal();await loadProjectData();render();openNode(id);toast('模型语义已保存，源码证据保留')}catch(err){toast(err.message,true);b.disabled=false}}}
function reviewNode(id){const n=getNode(id),r=reviews().get(id);modal('评审模型元素','记录你的领域判断，为后续修订与模型采用提供依据。',`<form id="review-form"><div style="margin-bottom:20px">${modelTag(n.model)}<h3 style="margin-top:12px;color:#9d7fb0">${esc(n.label)}</h3></div><div class="form-field"><label class="field-label" for="review-status">评审结论</label><select id="review-status" class="field-input"><option value="confirmed" ${r?.status==='confirmed'?'selected':''}>确认：语义与当前业务一致</option><option value="needs_changes" ${r?.status==='needs_changes'?'selected':''}>需修订：存在偏差或信息缺失</option><option value="pending" ${r?.status==='pending'?'selected':''}>保留待评审</option></select></div><div class="form-field"><label class="field-label" for="review-note">评审意见</label><textarea id="review-note" class="field-input" placeholder="说明确认依据、缺失信息或建议修订方向…">${esc(r?.note||'')}</textarea></div></form>`,`<small>结论按当前快照保存。</small><button class="button primary" type="submit" form="review-form" id="save-review">保存评审</button>`);$('review-form').onsubmit=async e=>{e.preventDefault();const b=$('save-review');b.disabled=true;try{await api(`/projects/${S.project.id}/reviews/${encodeURIComponent(id)}?snapshot=${S.data.snapshot.id}`,{method:'PUT',body:JSON.stringify({status:$('review-status').value,note:$('review-note').value})});closeModal();await refreshBootstrap();await loadProjectData();render();openNode(id);toast('评审结论已保存')}catch(err){toast(err.message,true);b.disabled=false}}}
async function showSource(path,line){modal('源码证据',path,`<div class="loading-state"><div class="loading-logo"></div><p>读取证据片段…</p></div>`,'',true);try{const s=await api(`/projects/${S.project.id}/source?snapshot=${S.data.snapshot.id}&path=${encodeURIComponent(path)}&line=${line}`);if(!$('modal-root').querySelector('.modal'))return;document.querySelector('.modal-body').innerHTML=`<div style="display:flex;align-items:center;gap:9px;margin-bottom:13px">${tag(s.snapshotSource?'分析快照内的源码':'原仓库源码','purple')}${s.modified?tag('当前文件与建模时内容不同','warning'):tag('证据内容匹配','success')}<small style="color:#b9a0c7">共 ${s.total} 行</small></div><div class="raw-code">${s.code.split('\n').map((text,i)=>`<div class="source-line ${s.from+i===s.line?'highlight':''}"><span class="line-number">${s.from+i}</span><span>${esc(text)||' '}</span></div>`).join('')}</div>`}catch(err){document.querySelector('.modal-body').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}}
function guide(){modal('让代码变成可理解的业务知识','Ontology Studio · 本地技术原型',`<div class="scope-list"><h3>01 / 接入代码仓库</h3><p>选择本地 Java / Spring 工程，或填写可访问的 HTTPS Git 地址。分析器只读取源码和必要配置。</p><h3>02 / 生成七模型</h3><p>在任务中心查看扫描、快照、建模和校验阶段。分析失败会保留具体原因，已完成的快照不受影响。</p><h3>03 / 探索与查证</h3><p>从业务域、对象关系或七模型列表进入；M6可展开条件分支，M7可查看输入参数、返回列和血缘状态。</p><h3>04 / 评审、修订与导出</h3><p>点击元素后可编辑名称和语义，保存评审结论。结果支持 JSON、七模型 YAML 与可离线阅读的 HTML。</p><h3>原型边界</h3><p>静态分析不代表运行验收。候选语义与已核验映射分开标识，缺失的审批角色和业务规则不补造。证据助手使用本地检索，没有调用外部大模型。</p></div>`)}
function commandPalette(){modal('搜索语义空间','搜索模型名称、标识或端点，快速定位到证据。',`<div class="palette"><input id="palette-query" placeholder="例如：清算、Loan、M7…" autocomplete="off"><div class="palette-results" id="palette-results"></div><div class="shortcuts"><span>点击结果查看模型</span><span>ESC 关闭</span></div></div>`);const input=$('palette-query');function result(){const q=input.value.toLowerCase().trim();const list=nodes().filter(n=>!q||JSON.stringify([n.label,n.id,n.endpoint]).toLowerCase().includes(q)).slice(0,35);$('palette-results').innerHTML=list.map(n=>`<button class="palette-result" data-palette-node="${esc(n.id)}">${modelTag(n.model)}<span class="palette-name">${esc(n.label)}<small>${esc(S.data.contexts[n.context]||n.context)}</small></span>${icon('chevron',13)}</button>`).join('')||'<div class="empty-state"><p>没有匹配的语义元素</p></div>';document.querySelectorAll('[data-palette-node]').forEach(b=>b.onclick=()=>{closeModal();openNode(b.dataset.paletteNode)})}input.oninput=result;result();input.focus()}
function renderAssistant(){const panel=$('assistant');panel.classList.remove('hidden');panel.innerHTML=`<div class="assistant-head"><span class="spark-icon">${icon('spark',21)}</span><div><b>证据助手</b><small>本地语义检索 · 不调用外部模型</small></div><button class="icon-button close" id="close-assistant" aria-label="关闭证据助手">${icon('close',17)}</button></div><div class="assistant-messages" id="assistant-messages">${S.assistantMessages.length?S.assistantMessages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text||'正在检索本地模型…')}${m.nodes?.length?`<div style="margin-top:10px">${m.nodes.map(n=>`<button class="related-node" data-node="${esc(n.id)}">${esc(n.model)} · ${esc(n.label)}<span>↗</span></button>`).join('')}</div>`:''}</div>`).join(''):`<div class="assistant-welcome"><h3>从一个问题开始</h3><p>围绕当前快照查找对象、流程与查询契约，每一个结果都可以回到源码。</p>${['支付有哪些流程','贷款有哪些对象','有哪些查询报表'].map(q=>`<button class="suggestion" data-suggestion="${q}">${q} ${icon('arrow',13)}</button>`).join('')}</div>`}</div><form id="assistant-form" class="assistant-form"><textarea id="assistant-input" placeholder="向当前业务本体提问…" required ${S.assistantBusy?'disabled':''}></textarea><div class="assistant-form-foot"><span>基于当前快照 · 只读查询</span><button class="button primary small" ${S.assistantBusy?'disabled':''}>${icon('arrow',14)}检索</button></div></form>`;$('close-assistant').onclick=()=>panel.classList.add('hidden');$('assistant-form').onsubmit=e=>{e.preventDefault();askAssistant($('assistant-input').value)};panel.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>askAssistant(b.dataset.suggestion));const messages=$('assistant-messages');messages.scrollTop=messages.scrollHeight;}
async function askAssistant(message){if(!S.data)return toast('请先选择已建模的项目',true);if(S.assistantBusy||!message.trim())return;S.assistantBusy=true;S.assistantMessages.push({role:'user',text:message},{role:'assistant',text:'',nodes:[]});const answer=S.assistantMessages.at(-1);renderAssistant();try{const r=await fetch('/api'+`/projects/${S.project.id}/assistant?snapshot=${S.data.snapshot.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});if(!r.ok){const d=await r.json();throw Error(d.error||'检索未完成')}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let p;while((p=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,p);buffer=buffer.slice(p+2);const name=block.match(/^event: (.+)$/m)?.[1],raw=block.match(/^data: (.+)$/m)?.[1];if(!raw)continue;const d=JSON.parse(raw);if(name==='delta')answer.text+=d.text;if(name==='render_payload')answer.nodes=d.nodes;}}}catch(err){answer.text='检索未完成：'+err.message}finally{S.assistantBusy=false;renderAssistant()}}
async function refreshBootstrap(){S.boot=await api('/bootstrap');if(S.project){const fresh=S.boot.projects.find(p=>p.id===S.project.id);if(fresh)S.project=fresh}renderNav()}
async function loadProjectData(){if(!S.project){S.data=null;return}const epoch=++loadEpoch;try{const [data,snaps]=await Promise.all([api(projectAPI('data')),api(projectAPI('snapshots'))]);if(epoch!==loadEpoch)return;S.data=data;S.projectSnapshots=snaps}catch(err){if(epoch!==loadEpoch)return;S.data=null;S.projectSnapshots=[];if(S.project.active_snapshot)toast(err.message,true)}}
async function chooseProject(id,goOverview=true){const p=S.boot.projects.find(p=>p.id===id);if(!p)return;S.project=p;S.snapshot=null;S.context='';S.type='';S.search='';S.page=1;S.flowId='';S.graphPrefs={};S.assistantMessages=[];localStorage.setItem('ontology-project',id);closeInspector();$('assistant').classList.add('hidden');await loadProjectData();if(goOverview&&S.route!=='overview')navigate('overview');else render()}
async function reanalyze(projectId=S.project?.id){if(!projectId)return newRepository();try{await api(`/projects/${projectId}/analyze`,{method:'POST',body:'{}'});await refreshBootstrap();navigate('jobs');if(S.route==='jobs')render();toast('分析任务已创建，源码将保持只读');schedulePoll()}catch(err){toast(err.message,true)}}
function schedulePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(async()=>{try{const old=S.project?.active_snapshot;await refreshBootstrap();if(S.project&&old!==S.project.active_snapshot&&!S.snapshot){await loadProjectData();render();toast('新的本体快照已生成')}else if(S.route==='jobs')render()}catch{}if(S.boot?.jobs.some(j=>['running','queued'].includes(j.status)))schedulePoll()},1600)}
document.addEventListener('click',async e=>{const route=e.target.closest('[data-route]');if(route){navigate(route.dataset.route);return}if(e.target.closest('[data-new]'))return newRepository();if(e.target.closest('[data-projects]'))return projectPicker();if(e.target.closest('[data-reanalyze]'))return reanalyze();if(e.target.closest('[data-close-modal]'))return closeModal();if(e.target.closest('[data-close-inspector]'))return closeInspector();const node=e.target.closest('[data-node]');if(node){$('assistant').classList.add('hidden');return openNode(node.dataset.node)}const flow=e.target.closest('[data-open-flow]');if(flow){S.flowId=flow.dataset.openFlow;S.flowSearch='';S.flowLevel='';S.context='';closeInspector();if(S.route==='flows')render();else navigate('flows');return}const src=e.target.closest('[data-source]');if(src)return showSource(src.dataset.source,Number(src.dataset.line)||1);const edit=e.target.closest('[data-edit]');if(edit)return editNode(edit.dataset.edit);const review=e.target.closest('[data-review]');if(review)return reviewNode(review.dataset.review);const model=e.target.closest('[data-model]');if(model){S.type=model.dataset.model;S.modelView='list';S.context='';S.search='';S.page=1;return navigate('models')}const domain=e.target.closest('[data-context]');if(domain){S.context=domain.dataset.context;S.type='';S.modelView='list';S.search='';S.page=1;return navigate('models')}
 const type=e.target.closest('[data-type]');if(type){S.type=type.dataset.type;S.page=1;return render()}const view=e.target.closest('[data-modelview]');if(view){S.modelView=view.dataset.modelview;return render()}const matrix=e.target.closest('[data-matrix-context]');if(matrix){S.context=matrix.dataset.matrixContext;S.type=matrix.dataset.matrixModel;S.modelView='list';S.page=1;return render()}const gm=e.target.closest('[data-graph-mode]');if(gm){S.graphMode=gm.dataset.graphMode;S.graphPrefs.focus='';closeInspector();return render()}const fp=e.target.closest('[data-flow]');if(fp){S.flowId=fp.dataset.flow;return render()}const page=e.target.closest('[data-page]');if(page&&!page.disabled){S.page=Number(page.dataset.page);return render()}const rt=e.target.closest('[data-reviewtab]');if(rt){S.reviewTab=rt.dataset.reviewtab;S.page=1;return render()}
 const cancel=e.target.closest('[data-cancel]');if(cancel){try{await api('/jobs/'+cancel.dataset.cancel+'/cancel',{method:'POST',body:'{}'});await refreshBootstrap();render();toast('已提交取消请求');schedulePoll()}catch(err){toast(err.message,true)}return}const retry=e.target.closest('[data-retry]');if(retry)return reanalyze(retry.dataset.retry);const jp=e.target.closest('[data-job-project]');if(jp)return chooseProject(jp.dataset.jobProject);const snap=e.target.closest('[data-snapshot]');if(snap){S.snapshot=snap.dataset.snapshot;await loadProjectData();render();return}if(e.target.closest('[data-scroll-yaml]'))return $('yaml-files').scrollIntoView({behavior:'smooth',block:'start'});
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(S.data)commandPalette();else toast('请先选择已建模的项目')}if(e.key==='Escape'){closeModal();closeInspector();$('assistant').classList.add('hidden')}if(e.key==='Enter'&&e.target.matches('tr[data-node]'))openNode(e.target.dataset.node)});
window.addEventListener('hashchange',()=>{S.route=location.hash.split('/')[1]||'overview';S.search='';S.page=1;closeInspector();$('sidebar').classList.remove('open');render()});$('project-switch').onclick=projectPicker;$('global-search').onclick=()=>S.data?commandPalette():toast('请先选择已建模的项目');$('assistant-toggle').onclick=()=>{if($('assistant').classList.contains('hidden')){closeInspector();renderAssistant()}else $('assistant').classList.add('hidden')};$('open-guide').onclick=guide;$('toggle-nav').onclick=()=>$('sidebar').classList.toggle('open');
async function init(){try{S.boot=await api('/bootstrap');S.project=S.boot.projects.find(p=>p.id===localStorage.getItem('ontology-project'))||S.boot.projects[0]||null;await loadProjectData();render();if(S.boot.jobs.some(j=>['running','queued'].includes(j.status)))schedulePoll()}catch(err){$('content').innerHTML=empty('本地服务暂不可用',esc(err.message),'<button class="button primary" id="retry-connection">重新连接</button>');$('retry-connection').onclick=init}}init();
